<script setup lang="ts">
import {computed,ref,watch,onMounted,onScopeDispose} from 'vue';import {useRoute} from 'vue-router';import {useI18n} from 'vue-i18n';import {readArticle,type ReaderArticle} from '../api/newsroom-reader';import {safeHref} from '../lib/navigation-links';
const route=useRoute(),{locale}=useI18n(),zh=computed(()=>locale.value==='zh-CN');const article=ref<ReaderArticle|null>(null),loading=ref(false),error=ref(false),translationDelayed=ref(false);let request:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined,attempts=0;
const dateLabel=computed(()=>{const a=article.value;if(!a)return '';if(a.sourceUpdatedAt&&!a.publishedAt)return (zh.value?'来源更新：':'Source updated: ')+new Date(a.sourceUpdatedAt).toLocaleString(locale.value);if(a.kind==='index-note'&&a.publishedAt)return (zh.value?'发布：':'Published: ')+new Date(a.publishedAt).toLocaleString(locale.value);if(a.format==='news-brief')return (zh.value?'简报核验：':'Brief checked: ')+a.reviewedDate;return (a.publishedAt?(zh.value?'赛果日期：':'Classification date: '):(zh.value?'索引发现：':'Indexed: '))+(a.publishedAt||a.indexedAt?new Date((a.publishedAt||a.indexedAt)!).toLocaleString(locale.value):'');});
const retryDelays=[4000,6000,10000,15000,20000];
function scheduleTranslation(){clearTimeout(timer);if(article.value?.translationStatus!=='pending')return;if(attempts>=retryDelays.length){translationDelayed.value=true;return;}timer=setTimeout(()=>{if(document.visibilityState==='visible'){attempts++;void load(true);}},retryDelays[attempts]);}
async function load(preserve=false){clearTimeout(timer);request?.abort();const current=new AbortController();request=current;loading.value=true;error.value=false;if(!preserve){article.value=null;attempts=0;translationDelayed.value=false;}try{const result=await readArticle(String(route.params.id),AbortSignal.any([current.signal,AbortSignal.timeout(20000)]));if(request===current&&!current.signal.aborted){article.value=result;if(result.translationStatus==='ready')translationDelayed.value=false;scheduleTranslation();}}catch{if(request===current&&!current.signal.aborted){error.value=true;if(preserve){translationDelayed.value=true;scheduleTranslation();}}}finally{if(request===current)loading.value=false;}}
function retryTranslation(){attempts=0;translationDelayed.value=false;void load(true);}
function resume(){if(document.visibilityState==='visible'&&article.value?.translationStatus==='pending'&&!loading.value&&attempts<retryDelays.length)void load(true);}
watch(()=>route.params.id,()=>{if(route.name==='newsroom-article')void load();},{immediate:true});onMounted(()=>document.addEventListener('visibilitychange',resume));onScopeDispose(()=>{request?.abort();clearTimeout(timer);document.removeEventListener('visibilitychange',resume);});
</script>
<template><article class="newsroom-reader legal-copy" :lang="locale"><RouterLink class="button" to="/newsroom">← {{zh?'返回新闻':'Back to news'}}</RouterLink><template v-if="article"><p class="eyebrow">NOBI / {{article.format==='news-brief'?(zh?'新闻简报':'NEWS BRIEF'):article.kind==='original'?(zh?'站内报道':'REPORT'):(zh?'新闻索引':'NEWS INDEX')}}</p><h1 tabindex="-1">{{zh?(article.titleZh||'中文标题翻译中'):article.title}}</h1><p class="caption">{{article.author}} · {{article.sourceName}} · {{dateLabel}}</p><p class="notice">{{zh?article.noticeZh:article.noticeEn}}</p><div v-if="zh&&(article.translationStatus==='pending'||article.translationStatus==='unavailable')" class="reader-translation-status" role="status"><p>{{translationDelayed||article.translationStatus==='unavailable'?'本次中文翻译未能及时完成。可以重试，或展开原题并查看来源。':'正在获取中文译文，完成后自动显示。'}}</p><button class="button" :disabled="loading" @click="retryTranslation">{{loading?'正在获取译文…':'重试中文翻译'}}</button></div><div class="prose"><p v-for="(p,i) in (zh?article.paragraphsZh:article.paragraphsEn)" :key="i">{{p}}</p><section v-for="(section,i) in article.sections" :key="i"><h2>{{zh?section.headingZh:section.headingEn}}</h2><ul><li v-for="(row,j) in section.rows" :key="j">{{zh?row.zh:row.en}}</li></ul></section></div><p v-if="article.backgroundSource" class="caption">{{zh?'补充数据署名：':'Reference data: '}}{{article.backgroundSource}}</p><details v-if="article.originalTitle"><summary>{{zh?'索引原题':'Indexed original headline'}}</summary><p>{{article.originalTitle}}</p></details><footer class="reader-source"><p>{{zh?'资料来源（可选查看）':'Source (optional)'}}</p><a :href="safeHref(article.sourceUrl)" :target="safeHref(article.sourceUrl)?.startsWith('#/')?undefined:'_blank'" rel="noopener noreferrer">{{article.sourceName}} ↗</a><template v-if="article.licenseUrl"> · <a :href="article.licenseUrl" target="_blank" rel="noopener noreferrer">CC BY 4.0 ↗</a></template></footer></template><p v-else-if="loading" role="status">{{zh?'正在加载新闻…':'Loading article…'}}</p><div v-else-if="error" role="alert"><h1>{{zh?'新闻暂不可用':'Article unavailable'}}</h1><p>{{zh?'该条目可能已超出当前新闻时间范围，或数据源暂时不可用。':'This entry may be outside the current news window or temporarily unavailable.'}}</p><button class="button" @click="load()">{{zh?'重试':'Retry'}}</button></div></article></template>
